use examen;
go
-------------------- Reset script --------------------
DROP TABLE IF EXISTS lo.DeliveryEvent;
DROP TABLE IF EXISTS lo.Fuel;
DROP TABLE IF EXISTS lo.Trip;
DROP TABLE IF EXISTS lo.Truck;
DROP TABLE IF EXISTS lo.[Load];
DROP TABLE IF EXISTS lo.Route;
DROP TABLE IF EXISTS lo.Customer;
DROP TABLE IF EXISTS lo.Driver;
DROP TABLE IF EXISTS lo.Facilities;

GO
DROP SCHEMA IF EXISTS lo;
GO
CREATE SCHEMA lo;
GO

-----------------------------------------------------

CREATE TABLE lo.Customer
(
    id                       INT 		  IDENTITY(1,1),
    customernumber           NVARCHAR(50) NOT NULL,
    name                     NVARCHAR(50) NOT NULL,
    [type]                   NVARCHAR(50) NOT NULL,
    creditTermsDays          TINYINT      NOT NULL,
    primaryFreightType       NVARCHAR(50) NOT NULL,
    accountStatus            NVARCHAR(50) NOT NULL,
    contractStartDate        DATE         NOT NULL,
    annualRevenuePotential   INT          NOT NULL,
    CONSTRAINT PK_Customer PRIMARY KEY (id)
);

CREATE TABLE lo.DeliveryEvent
(
    id                INT 		   IDENTITY(1,1),
    eventnumber       NVARCHAR(50) NOT NULL,
    loadId            INT          NOT NULL,
    tripId            INT          NOT NULL,
    [type]            NVARCHAR(50) NOT NULL,
    facilityId        INT		   NOT NULL,
    scheduledDatetime NVARCHAR(50) NOT NULL,
    actualDatetime    NVARCHAR(50) NOT NULL,
    detentionMinutes  TINYINT      NOT NULL,
    onTimeFlag        BIT          NOT NULL,
    locationCity      NVARCHAR(50) NOT NULL,
    locationState     NVARCHAR(50) NOT NULL,
    CONSTRAINT PK_DeliveryEvent PRIMARY KEY (id)
);

CREATE TABLE lo.Driver
(
    id               INT 		  IDENTITY(1,1),
    drivernumber     NVARCHAR(50) NOT NULL,
    firstname        NVARCHAR(50) NOT NULL,
    lastname         NVARCHAR(50) NOT NULL,
    hiredate         DATE         NOT NULL,
    terminationdate  DATE         NULL,
    licensenumber    NVARCHAR(50) NOT NULL,
    licensestate     NVARCHAR(50) NOT NULL,
    dateOfBirth      DATE         NOT NULL,
    homeTerminal     NVARCHAR(50) NOT NULL,
    employmentStatus NVARCHAR(50) NOT NULL,
    cdlClass         NVARCHAR(50) NOT NULL,
    yearsExperience  TINYINT      NOT NULL,
    CONSTRAINT PK_Driver PRIMARY KEY (id)
);

CREATE TABLE lo.Facilities
(
    id 					INT 		 IDENTITY(1,1),
    facilityNumber      NVARCHAR(50) NOT NULL,
    facilityName        NVARCHAR(50) NOT NULL,
    [type]              NVARCHAR(50) NOT NULL,
    city                NVARCHAR(50) NOT NULL,
    [state]             NVARCHAR(50) NOT NULL,
    latitude            FLOAT        NOT NULL,
    longitude           FLOAT        NOT NULL,
    dockDoors           TINYINT      NOT NULL,
    operatingHours      NVARCHAR(50) NOT NULL,
	CONSTRAINT PK_Facilities PRIMARY KEY (id)
);

CREATE TABLE lo.Fuel
(
    id INT 			IDENTITY(1,1),
    tripId          INT            NOT NULL,
    truckId         INT            NULL,
    driverId        INT            NULL,
    purchaseDate    DATETIME2(7)   NOT NULL,
    locationCity    NVARCHAR(50)   NOT NULL,
    locationState   NVARCHAR(50)   NOT NULL,
    gallons         FLOAT          NOT NULL,
    pricePerGallon  FLOAT          NOT NULL,
    totalCost       FLOAT          NOT NULL,
    fuelCardNumber  MONEY          NOT NULL,
	CONSTRAINT PK_Fuel PRIMARY KEY (id)
);

CREATE TABLE lo.[Load]
(
    id 				   INT 			 IDENTITY(1,1),
    customerId         INT           NOT NULL,
    routeId            INT           NOT NULL,
    loadDate           DATE          NOT NULL,
    loadType           NVARCHAR(50)  NOT NULL,
    weightLbs          INT           NOT NULL,
    pieces             TINYINT       NOT NULL,
    revenue            FLOAT         NOT NULL,
    fueSurcharge       FLOAT         NOT NULL,
    accessorialCharges TINYINT       NOT NULL,
    loadStatus         NVARCHAR(50)  NOT NULL,
    bookingType        NVARCHAR(50)  NOT NULL,
	CONSTRAINT PK_Load PRIMARY KEY (id)
);

CREATE TABLE lo.Route
(
    id 					  INT IDENTITY(1,1),
    routeNumber           NVARCHAR(50) NOT NULL,
    originCity            NVARCHAR(50) NOT NULL,
    originState           NVARCHAR(50) NOT NULL,
    destinationCity       NVARCHAR(50) NOT NULL,
    destinationState      NVARCHAR(50) NOT NULL,
    typicalDistanceMiles  SMALLINT     NOT NULL,
    baseRatePerMile       FLOAT        NOT NULL,
    fuelSurchargeRate     TIME(7)      NOT NULL,
    typicalTransitDays    TINYINT      NOT NULL,
	CONSTRAINT PK_Route PRIMARY KEY (id)
);

CREATE TABLE lo.Trip
(
    id 					INT 		  IDENTITY(1,1),
    loadId              INT           NOT NULL,
    driverId            INT           NULL,
    truckId             INT  		  NULL,
    dispatchDate        DATE          NOT NULL,
    actualDistanceMiles SMALLINT      NOT NULL,
    actualDurationHours FLOAT         NOT NULL,
    fuelGallonsUsed     FLOAT         NOT NULL,
    averageMpg          FLOAT         NOT NULL,
    idleTimeHours       FLOAT         NOT NULL,
    tripStatus          NVARCHAR(50)  NOT NULL,
	CONSTRAINT PK_Trip PRIMARY KEY (id)
);

CREATE TABLE lo.Truck
(
    id 					 INT 		   IDENTITY(1,1),
    unitNumber           SMALLINT      NOT NULL,
    make                 NVARCHAR(50)  NOT NULL,
    modelYear            SMALLINT      NOT NULL,
    vin                  NVARCHAR(50)  NOT NULL,
    acquisitionDate      DATE          NOT NULL,
    acquisitionMileage   INT           NOT NULL,
    fuelType             NVARCHAR(50)  NOT NULL,
    tankCapacityGallons  TINYINT       NOT NULL,
    status               NVARCHAR(50)  NOT NULL,
    homeTerminal         NVARCHAR(50)  NOT NULL,
	CONSTRAINT PK_Truck PRIMARY KEY (id)
);


-- FK CONSTRAINTS		
GO
ALTER TABLE [lo].[Deliveryevent]   ADD  CONSTRAINT [FK_Deliveryevent_Load] FOREIGN KEY([loadId])
REFERENCES [lo].[Load] ([id])

ALTER TABLE [lo].[Deliveryevent]   ADD  CONSTRAINT [FK_Deliveryevent_Trip] FOREIGN KEY([tripId])
REFERENCES [lo].[Trip] ([id])

ALTER TABLE [lo].[Deliveryevent]   ADD  CONSTRAINT [FK_Deliveryevent_Facilities] FOREIGN KEY([facilityId])
REFERENCES [lo].[Facilities] ([id])

GO
ALTER TABLE [lo].[Fuel]   ADD  CONSTRAINT [FK_Fuel_Driver] FOREIGN KEY([driverId])
REFERENCES [lo].[Driver] ([id])
GO
ALTER TABLE [lo].[Fuel]   ADD  CONSTRAINT [FK_Fuel_Trip] FOREIGN KEY([tripId])
REFERENCES [lo].[Trip] ([id])
GO
ALTER TABLE [lo].[Fuel]   ADD  CONSTRAINT [FK_Fuel_Truck] FOREIGN KEY([truckId])
REFERENCES [lo].[Truck] ([id])
GO
ALTER TABLE [lo].[Load]   ADD  CONSTRAINT [FK_Load_Customer] FOREIGN KEY([customerId])
REFERENCES [lo].[Customer] ([id])
GO
ALTER TABLE [lo].[Load] CHECK CONSTRAINT [FK_Load_Customer]
GO
ALTER TABLE [lo].[Load]   ADD  CONSTRAINT [FK_Load_Route] FOREIGN KEY([routeId])
REFERENCES [lo].[Route] ([id])

GO
ALTER TABLE [lo].[Trip]   ADD  CONSTRAINT [FK_Trip_Driver] FOREIGN KEY([driverId])
REFERENCES [lo].[Driver] ([id])

ALTER TABLE [lo].[Trip]   ADD  CONSTRAINT [FK_Trip_Load] FOREIGN KEY([loadId])
REFERENCES [lo].[Load] ([id])

ALTER TABLE [lo].[Trip]   ADD  CONSTRAINT [FK_Trip_Truck] FOREIGN KEY([truckId])
REFERENCES [lo].[Truck] ([id])

